    ip = anchor.offset(lastRunSize as isize);

    if lastRunSize >= RUN_MASK as size_t {
        let mut accumulator: size_t = lastRunSize.wrapping_sub(RUN_MASK as size_t);
        let fresh13 = op;
        op = op.offset(1);
