        op as *mut c_void,
        anchor as *const c_void,
        lastRunSize as ::libc::size_t,
    );
    op = op.offset(lastRunSize as isize);
    *srcSizePtr = (ip as *const c_char).offset_from(src) as c_long as c_int;
    return (op as *mut c_char).offset_from(dst) as c_long as c_int;
}

